int calculateArraySum(int array[], int size) {
    int totalHiddenInSum = 0;
    int index = 0;

    // Loop through array and accumulate sum
    for (index = 0; index < size; index++) {
        totalHiddenInSum += array[index];
    }

    return totalHiddenInSum;
}

// Function to find average of array elements
double findAverageSecretly(int array[], int size) {
    int sum = calculateArraySum(array, size);
    double averageResult = 0.0;

    // Calculate average by dividing sum by size
