```javascript
/**
 * Bubble Sort Algorithm Implementation
 * 
 * Time Complexity:
 * - Best Case: O(n) - when array is already sorted
 * - Average Case: O(n²)
 * - Worst Case: O(n²) - when array is sorted in reverse order
 * 
 * Space Complexity: O(1) - sorts in place
 * 
 * @param {number[]} arr - Array of integers to be sorted
 * @returns {number[]} - Sorted array in ascending order
 * @throws {Error} - If input validation fails
 */
function bubbleSort(arr) {
    // Input validation
    if (!Array.isArray(arr)) {
        throw new Error('Input must be an array');
    }

    if (arr.length === 0) {
        return arr;
    }

    if (arr.length > 100) {
        throw new Error('Array length exceeds maximum limit of 100 elements');
    }

    // Validate each element
    for (let i = 0; i < arr.length; i++) {
        if (typeof arr[i] !== 'number' || !Number.isInteger(arr[i])) {
            throw new Error(`Element at index ${i} is not an integer: ${arr[i]}`);
        }

        if (arr[i] < -10000 || arr[i] > 10000) {
            throw new Error(`Element at index ${i} is out of range [-10000, 10000]: ${arr[i]}`);
        }
    }

    // Create a copy to avoid mutating the original array
    const sortedArr = [...arr];
    const n = sortedArr.length;

    // Outer loop: controls the number of passes
    for (let i = 0; i < n - 1; i++) {
        let swapped = false; // Flag to optimize for already sorted arrays

        // Inner loop: performs comparisons and swaps
        // After each pass, the largest element "bubbles up" to its correct position
        for (let j = 0; j < n - i - 1; j++) {
            // Compare adjacent elements
            if (sortedArr[j] > sortedArr[j + 1]) {
                // Swap elements if they are in wrong order
                [sortedArr[j], sortedArr[j + 1]] = [sortedArr[j + 1], sortedArr[j]];
                swapped = true;
            }
        }

        // If no swaps occurred, array is already sorted
        // This optimization reduces best-case complexity to O(n)
        if (!swapped) {
            break;
        }
    }

    return sortedArr;
}

/**
 * Helper function to validate input before sorting
 * 
 * @param {any} input - Input to validate
 * @returns {Object} - Validation result with success flag and message
 */
function validateInput(input) {
    try {
        if (!Array.isArray(input)) {
            return { success: false, message: 'Input must be an array' };
        }

        if (input.length === 0) {
            return { success: true, message: 'Empty array is valid' };
        }

        if (input.length > 100) {
            return { success: false, message: 'Array exceeds maximum length of 100' };
        }

        for (let i = 0; i < input.length; i++) {
            if (typeof input[i] !== 'number' || !Number.isInteger(input[i])) {
                return { 
                    success: false, 
                    message: `Invalid element at index ${i}: must be an integer` 
                };
            }

            if (input[i] < -10000 || input[i] > 10000) {
                return { 
                    success: false, 
                    message: `Element at index ${i} out of range: must be between -10000 and 10000` 
                };
            }
        }

        return { success: true, message: 'Input is valid' };
    } catch (error) {
        return { success: false, message: error.message };
    }
}

